package scheduler

import (
	"encoding/json"
	"os"
	"reflect"
	"testing"
	"time"

	"github.com/7893/keepalive/internal/config"
	"github.com/7893/keepalive/internal/geo"
)

func TestLegacyPlansAndMetadata(t *testing.T) {
	// Captured from the previous release, rather than generated by Go under test.
	data, e := os.ReadFile("testdata/legacy-plans.json")
	if e != nil {
		t.Fatal(e)
	}
	type sample struct {
		Entry
		RequestID string  `json:"requestId"`
		Geo       geo.Geo `json:"geo"`
	}
	var fixtures []struct {
		Day     string   `json:"day"`
		Entries []sample `json:"entries"`
	}
	if e = json.Unmarshal(data, &fixtures); e != nil {
		t.Fatal(e)
	}
	for _, f := range fixtures {
		t.Run(f.Day, func(t *testing.T) {
			plan, e := Daily(f.Day)
			if e != nil {
				t.Fatal(e)
			}
			if len(plan) != len(f.Entries) {
				t.Fatalf("count %d != legacy %d", len(plan), len(f.Entries))
			}
			for i, entry := range plan {
				want := f.Entries[i]
				g, id := geo.Metadata(entry.Execution, entry.Service)
				if entry != want.Entry || g != want.Geo || id != want.RequestID {
					t.Fatalf("changed legacy slot %d: %#v %s %#v", i, entry, id, g)
				}
			}
		})
	}
}
func TestDailyCountsWindowsAndDistinctMinutes(t *testing.T) {
	seen := map[string]map[int]bool{}
	for _, s := range config.Services {
		seen[s.ID] = map[int]bool{}
	}
	independent := false
	for day := 1; day <= 31; day++ {
		date := time.Date(2026, 10, day, 0, 0, 0, 0, time.UTC).Format("2006-01-02")
		plan, e := Daily(date)
		if e != nil {
			t.Fatal(e)
		}
		minutes := map[string]bool{}
		windows := map[string]map[int]bool{}
		counts := map[string]int{}
		for _, entry := range plan {
			if minutes[entry.PlannedAt] {
				t.Fatal("shared minute")
			}
			minutes[entry.PlannedAt] = true
			stamp, _ := time.Parse(ISO, entry.PlannedAt)
			stamp = stamp.In(local)
			if stamp.Format("2006-01-02") != date {
				t.Fatal("wrong UTC+8 day")
			}
			if windows[entry.Service] == nil {
				windows[entry.Service] = map[int]bool{}
			}
			w := stamp.Hour() / 8
			if windows[entry.Service][w] {
				t.Fatal("shared window")
			}
			windows[entry.Service][w] = true
			counts[entry.Service]++
		}
		previous := 0
		for _, s := range config.Services {
			n := counts[s.ID]
			if n < 1 || n > 3 {
				t.Fatal("invalid daily count")
			}
			seen[s.ID][n] = true
			if previous != 0 && previous != n {
				independent = true
			}
			previous = n
		}
	}
	if !independent {
		t.Fatal("counts are tied")
	}
	for _, counts := range seen {
		if len(counts) != 3 {
			t.Fatal("counts do not vary")
		}
	}
	for _, date := range []string{"2026-02-29", "invalid", "2026-13-01"} {
		if _, e := Daily(date); e == nil {
			t.Fatal("invalid date accepted")
		}
	}
}
func TestDueSelectsEverySlotOnce(t *testing.T) {
	start := time.Date(2026, 10, 9, 16, 0, 0, 0, time.UTC)
	actual := []Entry{}
	for minute := 0; minute < 1440; minute++ {
		due, e := Due(start.Add(time.Duration(minute) * time.Minute).Format(ISO))
		if e != nil || len(due) > 1 {
			t.Fatal("invalid due selection", e)
		}
		actual = append(actual, due...)
	}
	want, _ := Daily("2026-10-10")
	if !reflect.DeepEqual(actual, want) {
		t.Fatal("missing or extra tasks")
	}
	for _, stamp := range []string{"", "2026-10-10", "2026-13-10T00:00:00Z"} {
		if _, e := Due(stamp); e == nil {
			t.Fatal("invalid timestamp accepted")
		}
	}
}
